VALUES ('d812e67e-5ecd-54f8-88f9-e69c48e0c82d', '30aef39c-5f6a-5913-8f8e-dd08854fe7ca', 'status', 'Status', 'Whether the place is in use. Set by the administrator; only ACTIVE locations are offered for new assignments. Expected but not yet in use. In use. Temporarily not used. Closed down. Removed from use altogether. A final state.', 1027, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
