INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8f56789e-7fa7-5449-9558-a2860d09f02f', 'Account', 'Maintain Account records', 'Create, find and maintain Account records. The list shows every Account you have access to — select a row to open it, or use New to add one. Each row is a single Account, described by 8 fields.

Id is unique: no two Account records may share the same value, and a save that would duplicate one is rejected. Code, Name, Account Type and Status must be filled in before the record can be saved.

Every Account points at Currency and Organization. Choose the linked record from the lookup on those fields rather than typing an identifier. Journal Entry Line and Budget Line refer back to Account, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Account then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Account with no rules or workflows attached is marked Final immediately.', 'landmark', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b1507289-b12c-52bd-a713-ae1175199f23', 'bus_account', 'Account', 'A ledger account in a chart of accounts: the named bucket to which monetary activity is posted and from which balances are reported. Account is how an organisation classifies money. Every posting lands on an account, and the account''s type decides which statement it appears on (balance sheet or income statement) and which direction increases its balance. Created when the chart of accounts is set up or extended; referenced by journal postings, invoices, payments, budgets and financial reports. Accounts are retired, never deleted, so past postings stay explainable. Accounts form a tree through parent and child accounts so balances roll up into reporting groups; each chart belongs to an Organization, and an account may be pinned to a Currency for foreign-currency ledgers. Active accounts accept postings. Inactive accounts are paused and can be reactivated. Retired accounts are closed for good but remain in reports covering the periods in which they were used. Account 4000 "Product Revenue" (type REVENUE) is a child of 4000-series "Revenue"; every sales invoice line posts to it, and the income statement sums it into total revenue.', 'landmark', 'A', FALSE, FALSE, FALSE, TRUE, '8f56789e-7fa7-5449-9558-a2860d09f02f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('32997f2f-78e8-50b0-8e20-fc39f3729c58', '8f56789e-7fa7-5449-9558-a2860d09f02f', 'b1507289-b12c-52bd-a713-ae1175199f23', 'Account', 'Shows one Account at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency and Organization are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4fbeeac4-c49f-5da2-b063-06a5b783f56f', 'b1507289-b12c-52bd-a713-ae1175199f23', 'id', 'Id', 'The permanent system identity of the ledger account. Generated when the account is created and never changed; postings, budgets and reports hold this identity so renumbering the account code does not break them.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81322f04-c05e-5b4e-bad5-223589a074d7', 'b1507289-b12c-52bd-a713-ae1175199f23', 'code', 'Code', 'The account number or code under which the account appears in the chart of accounts, such as 1100 or 4000. Entered by the finance team when creating the account and used for lookup, sorting and imports. It must be unique within its chart, and finance teams usually structure it so the leading digits indicate the account class.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('df5a8986-72ba-5541-9def-fb763ef86f8d', 'b1507289-b12c-52bd-a713-ae1175199f23', 'name', 'Name', 'The descriptive title of the account, such as Accounts Receivable or Product Revenue. Shown on ledgers, trial balances and statements. It can be reworded for clarity without affecting history because postings refer to the account by identity.', 10, 300, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd0f64b9-8f41-585b-a946-a75439a67406', 'b1507289-b12c-52bd-a713-ae1175199f23', 'account_type', 'Account Type', 'The accounting class of the account, which decides where it appears in the statements and whether debits or credits increase it. Chosen when the account is created and rarely changed afterwards, because changing it reclassifies every historical posting. Reports group and sign balances by this value. Something the organisation owns or is owed, such as cash or receivables; debits increase it and it appears on the balance sheet. Something the organisation owes, such as payables or loans; credits increase it and it appears on the balance sheet. The owners'' residual interest, such as share capital and retained earnings; credits increase it and it appears on the balance sheet. Income earned from the organisation''s activities; credits increase it and it appears on the income statement. Cost incurred in earning revenue; debits increase it and it appears on the income statement. An account that offsets another, such as accumulated depreciation against an asset or sales returns against revenue; it carries the opposite sign of the account it offsets.', 1000, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e6c40d4d-a0b8-5c46-a77b-2f54bc9958dc', 'b1507289-b12c-52bd-a713-ae1175199f23', 'status', 'Status', 'Whether the account is open for new postings. New accounts start ACTIVE. Finance staff move an account to INACTIVE to stop postings temporarily and to RETIRED when it is closed for good; posting screens offer only ACTIVE accounts. Open for postings and shown in account pick-lists. Paused: no new postings are accepted, but it can be reactivated and still appears in reports. Closed for good: no postings, kept only so historical periods stay reportable.', 1001, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e0510fe6-60cc-5eba-a756-756fe275ad26', 'b1507289-b12c-52bd-a713-ae1175199f23', 'currency_id', 'Currency', 'The currency in which this account is denominated, when it is held in something other than the organisation''s base currency. Set for foreign-currency accounts such as a euro bank account so that postings and balances are held in that currency; left empty for ordinary base-currency accounts. Points to Currency so foreign-currency balances can be revalued into the reporting currency.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0ab764e7-52a6-5dd4-a1ec-73b6f7ed5790', 'b1507289-b12c-52bd-a713-ae1175199f23', 'parent_account_id', 'Parent Account', 'The account directly above this one in the chart of accounts hierarchy. Chosen when the account is created to place it in a reporting group, for example Bank Accounts under Current Assets. Leave empty for a top-level account. At most one parent: the chart is a tree, so an account sits in exactly one place or at the top. Lets reports roll balances up the tree; a cycle would make roll-up impossible, which is why the hierarchy must stay acyclic.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1c870dd7-6237-5e7c-9e6d-2fe7dd5af351', 'b1507289-b12c-52bd-a713-ae1175199f23', 'organization_id', 'Organization', 'The organisation whose chart of accounts this account belongs to. Set when the account is created so each legal entity keeps its own chart; used to scope ledgers and reports to one organisation. At most one organisation; an account with none is treated as shared across the chart it is loaded into. Keeps one organisation''s ledger from mixing with another''s in consolidated or multi-entity setups.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
