INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('71372abd-3b16-5900-b2e2-a16452785cdf', '878be901-080d-55e8-b777-413d10f02110', 'id', 'Id', 'The identity of the accounting entry. Generated on creation; ledger lines and audit refer to it. Identifies the accounting event independently of its source transaction and journal lines. Provides the stable root reference across accounting preparation, validation, posting, reporting and reversal.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
