INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3d38889a-49bf-5440-ad90-988265efe308', '56dcdcbd-9992-57a9-af6d-58132e5d9933', 'e6eeaa77-cf39-57d1-862f-47edebb3799e', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'The identity of the payment, separate from the bank''s reference. Generated on creation; allocations, ledger entries and bank matches refer to it. Identifies the financial movement independently of its business reference, allocations, bank evidence, accounting entries or credit settlement purpose. Identity remains stable when allocations are reversed or a refund/settlement is associated with a credit note. Root reference across preparation, authorization, posting, clearing and reversal. Must be unique: a save is rejected if another Payment already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('671dfd2e-bb08-5e6d-b54e-d109a122b02e', '56dcdcbd-9992-57a9-af6d-58132e5d9933', '7e9262f0-1700-55e4-b496-26705b88c93b', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Payment Number', 'The number under which the payment is recorded and quoted. Allocated from a number series; unique; shown on remittance advices and receipts. Reference communicated in remittance, statements, bank reconciliation and payment inquiries. Distinct from paymentId and bank transaction identifiers. Correlates internal payment evidence with operational and external references. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Payment already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a343dfc9-f811-5b9e-bdaa-f6eb5f3c5d7c', '56dcdcbd-9992-57a9-af6d-58132e5d9933', '52b23b18-7767-5db4-b03a-ff6a43212349', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Payment Date', 'Timestamp at which the payment event is recognized by the business process. Establishes internal settlement chronology. Accounting periods, cash reporting, reconciliation and settlement analysis. Distinct from bank value date, clearing date, posting date, allocation date and credit-note date. Provides event time for internal payment processing. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6cb7e9f-8390-5880-8a68-32d972f01d88', '56dcdcbd-9992-57a9-af6d-58132e5d9933', '2256ad63-8ee0-5787-ab11-40002a2d6a33', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Direction', 'Whether money is coming in or going out. Set when the payment is created; decides whose account is debited and credited. Money received from a payer. Money paid out to a payee. Establishes cash-flow direction and payer/payee interpretation. Customer refund and supplier-credit refund/settlement payments are DISBURSEMENT events and never rewrite original receipt payments. Determines cash-flow and settlement path. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('be1fef73-a9c2-5ee7-99ca-404a5fbb4c26', '56dcdcbd-9992-57a9-af6d-58132e5d9933', '6072c82b-7ec3-5b93-a433-b6d97bb41976', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Status', 'How far the payment has progressed from preparation to clearing. Moved by treasury and the bank reconciliation process. Being prepared; no financial effect. Authorised but not yet recorded in the books. Recorded in the ledger but not yet confirmed by the bank. Confirmed by bank evidence. A final state. Cancelled and of no effect. A final state. Cancelled after posting by a compensating entry. A final state. Indicates authorization, internal recognition, external clearing, invalidation or reversal. Independent of Invoice, CreditNote, SupplierCreditNote and BankTransaction statuses. APPROVED authorizes processing; POSTED recognizes internally; CLEARED confirms external evidence; VOID/REVERSED handle correction. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d3c0b785-7c34-5dd9-bea5-8413d320c30e', '56dcdcbd-9992-57a9-af6d-58132e5d9933', 'b11b04e0-76b1-5728-9769-e5dffdbc3866', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Amount', 'Total monetary value of the payment event. Represents money received or disbursed, not the amount allocated to one claim or credit. Cash position, allocation validation, accounting and reconciliation. PaymentAllocation distributes receipt payments; a credit-settlement payment settles an explicit customer or supplier credit obligation. Provides source monetary amount. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b80bcbef-49d5-5389-9b81-435a01b8e966', '56dcdcbd-9992-57a9-af6d-58132e5d9933', '93b7b60a-48e9-57e0-b247-6048f5cfa02c', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Currency', 'Currency denomination of the payment. Defines interpretation of payment amount. Allocation, exchange-rate selection, bank reconciliation, accounting and reporting. May differ from invoice or credit currency only with explicit ExchangeRate evidence. Establishes source currency. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d4f39a0-810d-5998-9d8e-5d8e2ececdca', '56dcdcbd-9992-57a9-af6d-58132e5d9933', '6cb89af7-1b82-5571-9d36-96d62ea19e98', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Payment Method', 'How the money is moved. Chosen when the payment is created; decides processing and fees. Notes and coins. An electronic transfer between bank accounts. A payment card. A paper cheque. A debit collected under a mandate. Any other method. Describes how money moves rather than which obligation it settles. Refund or supplier-credit settlement method must satisfy applicable policy. Determines expected settlement evidence. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
