VALUES ('cc271510-30ac-5df0-9c95-99723674beeb', '942a3485-c189-531c-9889-b8cf580daa79', 'valid_from', 'Valid From', 'The first date on which the role applies. Set when the role is assigned. Works with validTo and status; ending a role does not delete Party identity or other roles. Prevents premature use of a newly established role.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
