VALUES ('9ca168c2-a0fc-5078-b3ab-94dfa903929d', 'fcab9907-6866-59c7-be62-b7268427e7a8', 'cc271510-30ac-5df0-9c95-99723674beeb', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Valid From', 'The first date on which the role applies. Set when the role is assigned. Works with validTo and status; ending a role does not delete Party identity or other roles. Prevents premature use of a newly established role.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
