VALUES ('3852e38c-4b0d-5a08-bcc6-64ef2283267f', 'cc1176ab-edc6-5c48-a33e-0496d30e1a55', 'd87526f4-e247-52a9-b1e3-7a2338cb4bf2', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'The identity of the order, constant for its life. Generated on creation; shipments and invoices refer to it. Referenced by every document that follows the order. Must be unique: a save is rejected if another Sales Order already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
