INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b5c47c20-d102-5c55-94bd-b99d5aacfc12', 'cc1176ab-edc6-5c48-a33e-0496d30e1a55', '3d33219c-7ad8-5f87-8bd9-ba0f1f89c11e', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Order Number', 'The number the customer sees, such as SO-10482. Unique; quoted on confirmations and invoices. Used to find the order from any following document. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Sales Order already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
