INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ee03f28f-81fb-56bf-89cb-abb4c9ed97d3', 'cc1176ab-edc6-5c48-a33e-0496d30e1a55', 'daa46309-0317-5cf2-9d32-cc017a992fb6', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Order Date', 'When the order was placed. Set on entry; sales are reported by it. Compared with the requested delivery date. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e3fa68ce-99ba-5f34-b8cf-bfb82497cb76', 'cc1176ab-edc6-5c48-a33e-0496d30e1a55', 'e511ae8a-d7ce-5184-8413-f695ceb48fc4', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Status', 'Being entered; not yet binding on either side. Accepted by the business; the commitment stands. Stock has been reserved to meet the order. Part of the order has been shipped. Everything ordered has been delivered. A final state. Withdrawn before fulfilment. A final state. Order-level lifecycle state controlling commercial and fulfillment permissions. Drives confirmation, allocation, fulfillment, shipment readiness and cancellation. Summarizes downstream evidence; it is not an independent source of fulfillment quantity. Status transitions are validated against line, reservation, shipment and fulfillment evidence. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5f129907-8709-5450-8d35-1cc1cf9e17d2', 'cc1176ab-edc6-5c48-a33e-0496d30e1a55', '9ce8739c-58da-5317-9d70-e810ae21ec95', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Currency', 'Chosen when the order is created; all amounts are in it. Read with the total. The currency id of the sales order: a link to another record the business records on it.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a0cdbbd7-cf85-53d5-ba63-d0691edb5a45', 'cc1176ab-edc6-5c48-a33e-0496d30e1a55', '32042591-dd0e-54bb-bf91-02661dfde191', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Requested Delivery Date', 'Entered from the customer''s request; used to plan allocation and shipping. Compared with the promised and actual shipment dates. The requested delivery date of the sales order: a calendar date the business records on it.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
