-- Budget (bus_budget)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('88ec5c7a-a6fe-5f7b-aab3-a8badfedeaa6', 'Budget', 'Maintain Budget records', 'Create, find and maintain Budget records. The list shows every Budget you have access to — select a row to open it, or use New to add one. Each row is a single Budget, described by 6 fields.

Id is unique: no two Budget records may share the same value, and a save that would duplicate one is rejected. Code, Status and Organization must be filled in before the record can be saved.

Every Budget points at Organization, Fiscal Period and Scenario. Choose the linked record from the lookup on those fields rather than typing an identifier. Budget Line and Variance refer back to Budget, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Budget then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Budget with no rules or workflows attached is marked Final immediately.', 'piggy-bank', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'bus_budget', 'Budget', 'Governed financial planning baseline. Budget records intended/authorized financial amounts while JournalEntry records actual accounting. Planning, spending control and variance reporting. BudgetLine supplies dimensional detail; FiscalPeriod supplies accounting time; Scenario supplies planning assumptions. Draft to submitted to approved/active to superseded/closed.', 'piggy-bank', 'A', FALSE, FALSE, FALSE, TRUE, '88ec5c7a-a6fe-5f7b-aab3-a8badfedeaa6', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8080a08e-4d03-5f0e-bd22-325ea8a29b72', '88ec5c7a-a6fe-5f7b-aab3-a8badfedeaa6', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'Budget', 'Shows one Budget at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Organization, Fiscal Period and Scenario are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('795f3e78-51c6-5f14-8e41-84fbfa9d57fe', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'id', 'Id', 'The identity of the budget, stable across revisions of its figures. Identifies one financial plan version. Planning, approval, control and reporting. Owns BudgetLines and references planning context.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e0923513-f9d7-5141-801b-aca339ddff56', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'code', 'Code', 'Assigned by finance when the budget is created, for example FY26-OPS-V1; used to find the budget and cite it in approvals. Business budget code. Human/integration reference for plan. Unique within organization/version policy.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0585d7aa-4f30-557a-8e0a-a80977ea122a', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'status', 'Status', 'Being prepared by the budget owner; figures may change freely. Sent for approval; changes are held while it is reviewed. Accepted by the authorising body but not yet the live control. The live budget against which spending is monitored. Replaced by a later version; kept as the record of what was once approved. The period is over and the budget is closed for comparison with actuals. Budget governance state. Controls editability and authoritative planning use. Approval and control. Actual accounting remains in JournalEntry.', 1009, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a6343799-5224-5ad4-8314-64df0d1a61a9', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'organization_id', 'Organization', 'Set when the budget is created; determines whose spending the budget limits. Exactly one organisation: a budget always plans the money of a single organisation. Organization owning budget. Defines planning boundary. Accounting dimensions must belong to compatible context.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5b46223d-ac86-5616-8388-beaa13db2a41', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'fiscal_period_id', 'Fiscal Period', 'Fiscal period governed by budget. Aligns plan with accounting time. Budget control and variance. Optional when budget spans multiple periods represented by lines. Does not open/close accounting period.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('54cf5684-9921-5daa-b1f6-7582207dbb1d', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'scenario_id', 'Scenario', 'Planning scenario represented. Distinguishes baseline/upside/downside etc. Comparative planning. Optional for single-scenario plans. Scenario never changes actual ledger.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
