INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e45f5e17-981f-5f7d-8efb-8fffec5aada8', 'Variance', 'Maintain Variance records', 'Create, find and maintain Variance records. The list shows every Variance you have access to — select a row to open it, or use New to add one. Each row is a single Variance, described by 5 fields.

Id is unique: no two Variance records may share the same value, and a save that would duplicate one is rejected. Code and Organization must be filled in before the record can be saved.

Every Variance points at Organization, Budget and Forecast. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Variance then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Variance with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ce370c1f-fb97-5f24-bd7d-d9e58fcf6e12', 'bus_variance', 'Variance', 'A comparison between planned, forecast or actual financial measures for a period and dimension. A variance shows how far reality is from the plan and in which direction. It lets managers see where budget is overspent or revenue falls short, without altering the accounting entries it is derived from. Calculated by finance or the planning system; read by managers and budget owners. A variance belongs to an organisation and compares a budget or a forecast with actuals. A variance is calculated for a period and recalculated as actuals arrive. It never changes the entries it compares. Marketing spend is 12 percent over budget for March.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, 'e45f5e17-981f-5f7d-8efb-8fffec5aada8', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
