INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dbab7b63-bbee-52a4-a311-c15c6678e7f3', 'Fiscal Period', 'Maintain Fiscal Period records', 'Create, find and maintain Fiscal Period records. The list shows every Fiscal Period you have access to — select a row to open it, or use New to add one. Each row is a single Fiscal Period, described by 6 fields.

Id is unique: no two Fiscal Period records may share the same value, and a save that would duplicate one is rejected. Code, Start Date, End Date, Status and Organization must be filled in before the record can be saved.

Every Fiscal Period points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier. Journal Entry, Budget and Forecast refer back to Fiscal Period, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Fiscal Period then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Fiscal Period with no rules or workflows attached is marked Final immediately.', 'database', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4e683bf5-1160-58d8-9b40-5963336c4df9', 'bus_fiscal_period', 'Fiscal Period', 'Accounting-period control for posting, close and reporting. FiscalPeriod determines whether an accounting date is currently eligible for recognition; it does not replace JournalEntry. General ledger, AP, AR, treasury, assets, inventory accounting, tax and financial close. Organization defines books; JournalEntry carries accounting date; period state controls posting eligibility. Future → open → soft closed → closed → locked, with governed reopen where policy permits. Closing/reopening immediately revalidates pending postings and close processes while preserving already posted history.', 'database', 'A', FALSE, FALSE, FALSE, TRUE, 'dbab7b63-bbee-52a4-a311-c15c6678e7f3', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2003a1eb-fd7a-5306-bb33-f60173a9cbd9', 'dbab7b63-bbee-52a4-a311-c15c6678e7f3', '4e683bf5-1160-58d8-9b40-5963336c4df9', 'Fiscal Period', 'Shows one Fiscal Period at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Organization is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('889e544c-92de-5afb-8c6d-ea8b17f249a0', '4e683bf5-1160-58d8-9b40-5963336c4df9', 'id', 'Id', 'Stable fiscal-period identity. Identifies one accounting control interval independently of its label. Posting, close, reporting and audit. JournalEntry accounting dates resolve to an eligible period.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9da039fc-3549-5b66-8d1f-fd62294c83b7', '4e683bf5-1160-58d8-9b40-5963336c4df9', 'code', 'Code', 'Business period code. Human-facing accounting interval reference such as 2026-09. Journals, close and reports. Unique within organization/calendar context.', 10, 50, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07ee073b-18ff-50e7-a911-19e36eaa8dc6', '4e683bf5-1160-58d8-9b40-5963336c4df9', 'start_date', 'Start Date', 'First accounting date in period. Defines lower posting boundary. Period determination. Inclusive with endDate.', 15, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0a83e5f9-df05-5d4c-acc8-49e5ef6655fa', '4e683bf5-1160-58d8-9b40-5963336c4df9', 'end_date', 'End Date', 'The last day covered by the accounting period. Set when the calendar is defined; must not be before the start date. Postings dated after it belong to a later period. Together with the start date it defines the interval in which journal entries may be dated. Defines upper posting boundary.', 15, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
