VALUES ('08efa3f4-abfe-5d76-94a1-e2de8839683a', '4e683bf5-1160-58d8-9b40-5963336c4df9', 'organization_id', 'Organization', 'Exactly one organisation: each legal entity keeps its own accounting calendar and closes its own periods. Accounting organization owning period. Establishes books/control boundary. Posting and reporting. Journal organization must match.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
