INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('30640d82-f863-527c-9056-090ac0d6e66d', 'Tax Code', 'Maintain Tax Code records', 'Create, find and maintain Tax Code records. The list shows every Tax Code you have access to — select a row to open it, or use New to add one. Each row is a single Tax Code, described by 3 fields.

Id is unique: no two Tax Code records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Tax Code points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tax Code then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tax Code with no rules or workflows attached is marked Final immediately.', 'percent', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a49b266-ca2f-5fd7-aeca-411ee3350bf7', 'bus_tax_code', 'Tax Code', 'A tax classification code used to choose the tax rules, rates, registrations and reporting treatment that apply. A tax code lets a product, service or transaction be given its tax treatment by name instead of retyping rules. It keeps tax decisions consistent and makes it clear why a given rate was charged. Maintained by tax or finance; chosen on products, lines and accounts; read by tax calculation and returns. A tax code may belong to an organisation and is used with jurisdictions and rates. A tax code is drafted, active while it is used, and completed when no longer used. It may be cancelled before use. Completed and cancelled are final; past transactions keep it. Code "STD-20" marks goods taxed at the standard rate of twenty percent.', 'percent', 'A', FALSE, FALSE, FALSE, TRUE, '30640d82-f863-527c-9056-090ac0d6e66d', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('36a074b8-283f-5026-b3e6-2536e42b24b3', '30640d82-f863-527c-9056-090ac0d6e66d', '4a49b266-ca2f-5fd7-aeca-411ee3350bf7', 'Tax Code', 'Shows one Tax Code at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Organization is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
