INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07eeff62-bfd1-5643-a3ed-98309f2aae6e', 'Tax Registration', 'Maintain Tax Registration records', 'Create, find and maintain Tax Registration records. The list shows every Tax Registration you have access to — select a row to open it, or use New to add one. Each row is a single Tax Registration, described by 3 fields.

Id is unique: no two Tax Registration records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Tax Registration points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tax Registration then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tax Registration with no rules or workflows attached is marked Final immediately.', 'percent', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd8d790d-379e-591d-948d-5c1c80ba5399', 'bus_tax_registration', 'Tax Registration', 'The registration of a party or organisation with a tax jurisdiction and its tax authority. A registration is the tax identity the business holds in a place, such as a VAT number. Recording it shows where the business may charge and must report tax and which number to print on invoices. Maintained by tax staff; read when invoicing and filing returns. A registration may belong to an organisation and is held in a jurisdiction. A registration is drafted, active while valid and completed when it ends. It may be cancelled before use. Completed and cancelled are final. The company''s VAT registration in Germany, active since March 2022.', 'percent', 'A', FALSE, FALSE, FALSE, TRUE, '07eeff62-bfd1-5643-a3ed-98309f2aae6e', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
