-- --------------------------------------------------------------------------
-- Tax Transaction (bus_tax_transaction)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3a39cfd8-9205-5dfc-82b7-32ee9e799756', 'Tax Transaction', 'Maintain Tax Transaction records', 'Create, find and maintain Tax Transaction records. The list shows every Tax Transaction you have access to — select a row to open it, or use New to add one. Each row is a single Tax Transaction, described by 3 fields.

Id is unique: no two Tax Transaction records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Tax Transaction points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tax Transaction then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tax Transaction with no rules or workflows attached is marked Final immediately.', 'percent', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3c4be291-0df3-5f3b-b306-897618284b0d', 'bus_tax_transaction', 'Tax Transaction', 'The tax consequence of a taxable business transaction, kept apart from payment and ledger posting. A tax transaction records how much tax arose on a sale or purchase and under what treatment. Keeping it on its own lets tax be reported and checked without changing the payment or accounting records. Created automatically from taxable documents; read by tax returns and audit. A tax transaction may belong to an organisation and follows a taxable document. A tax transaction is drafted, becomes active when reportable and completed once reported. It may be cancelled before. Completed and cancelled are final. The 20 tax charged on invoice INV-3041 is recorded as a tax transaction for the March VAT return.', 'percent', 'A', FALSE, FALSE, FALSE, TRUE, '3a39cfd8-9205-5dfc-82b7-32ee9e799756', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('616b6736-5c4a-5a52-81e5-62aac491cdaa', '3a39cfd8-9205-5dfc-82b7-32ee9e799756', '3c4be291-0df3-5f3b-b306-897618284b0d', 'Tax Transaction', 'Shows one Tax Transaction at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Organization is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7474278e-a213-5665-9c36-21ae303d05b5', '3c4be291-0df3-5f3b-b306-897618284b0d', 'id', 'Id', 'The identity of the tax transaction, constant for its life. Lets returns and the source document point at the same tax record. Generated on creation. Referenced by returns.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d8c41a9-3ff2-5a62-877c-cb95881a8e10', '3c4be291-0df3-5f3b-b306-897618284b0d', 'status', 'Status', 'Where the tax transaction is in reporting. Shows whether the tax has been reported. Starts as DRAFT; moved by tax staff and returns. Only active transactions are included in a return. Calculated and not yet confirmed. Confirmed and due to be reported. Reported or settled. A final state. Withdrawn, for example after a credit. A final state.', 1065, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0505b629-1f19-5910-98ff-9b5105afb364', '3c4be291-0df3-5f3b-b306-897618284b0d', 'organization_id', 'Organization', 'The organisation the tax is reported by. Chosen from the source document. At most one organisation. Decides which company''s return includes it.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
