-- --------------------------------------------------------------------------
-- Billing Cycle (bus_billing_cycle)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('19408719-fd23-5791-b8bb-fab71c7ccae8', 'Billing Cycle', 'Maintain Billing Cycle records', 'Create, find and maintain Billing Cycle records. The list shows every Billing Cycle you have access to — select a row to open it, or use New to add one. Each row is a single Billing Cycle, described by 2 fields.

Id is unique: no two Billing Cycle records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Billing Cycle then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Billing Cycle with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('41ee5dd3-dddb-542f-8803-28f68e35908c', 'bus_billing_cycle', 'Billing Cycle', 'A recurring billing interval with its cut-off, which decides which period''s charges a billing run picks up. Billing happens on a rhythm, such as monthly on the first. A billing cycle defines that rhythm, so charges are collected into the right invoice period and no charge is billed twice or missed. Defined by the billing team; assigned to accounts or contracts; read by billing runs to decide the period and cut-off for charge generation. Customers, contracts or subscriptions are assigned a cycle; the billing run generates charges for the period it defines. A cycle is drafted, active while it drives billing, completed when it is no longer used and cancelled if withdrawn before use. It must not rewrite charges already generated. A monthly cycle that closes on the last day of the month and invoices on the first working day of the next.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '19408719-fd23-5791-b8bb-fab71c7ccae8', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('08a4602b-0d83-5f07-b785-2d5366443925', '19408719-fd23-5791-b8bb-fab71c7ccae8', '41ee5dd3-dddb-542f-8803-28f68e35908c', 'Billing Cycle', 'Shows one Billing Cycle at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
