INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d3c053a6-3890-572e-969d-31453c821531', 'Charge', 'Maintain Charge records', 'Create, find and maintain Charge records. The list shows every Charge you have access to — select a row to open it, or use New to add one. Each row is a single Charge, described by 3 fields.

Id is unique: no two Charge records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Charge points at Customer. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Charge then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Charge with no rules or workflows attached is marked Final immediately.', 'file-text', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('353974a7-97dd-53ad-9b9b-c73f2da5814c', 'bus_charge', 'Charge', 'A billable amount produced from a subscription, usage, service, product, fee or adjustment rule, before it is settled. A charge is the line between something the customer received and something they will be invoiced for. Holding it as a record lets billing check, adjust or cancel amounts before they become part of an invoice. Generated by billing runs and manual adjustments; reviewed before invoicing; read when a customer queries what they were billed for. A charge belongs to the Customer it is billed to. It never replaces the invoice, payment or ledger entries that follow from it. A charge is drafted, becomes active when ready to bill, completes when it has been invoiced and cancelled if it should not be billed. It does not rewrite cash, accounting or tax records. A monthly platform fee of 49.00 for March, generated by the billing cycle for a subscriber account.', 'file-text', 'A', FALSE, FALSE, FALSE, TRUE, 'd3c053a6-3890-572e-969d-31453c821531', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2e0475ad-ecf0-5e9d-9c32-1e607c3f1764', 'd3c053a6-3890-572e-969d-31453c821531', '353974a7-97dd-53ad-9b9b-c73f2da5814c', 'Charge', 'Shows one Charge at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Customer is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
