INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2e53cd1a-834b-5a77-9a8d-7c1925acb59d', 'Subscription Plan', 'Maintain Subscription Plan records', 'Create, find and maintain Subscription Plan records. The list shows every Subscription Plan you have access to — select a row to open it, or use New to add one. Each row is a single Subscription Plan, described by 2 fields.

Id is unique: no two Subscription Plan records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Subscription Plan then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Subscription Plan with no rules or workflows attached is marked Final immediately.', 'repeat', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d576d220-154b-5abf-b4d4-090d287ba1e3', 'bus_subscription_plan', 'Subscription Plan', 'A reusable commercial plan that sets the recurring charges, usage, entitlements and billing terms of subscriptions. A plan is the product definition of a subscription. Defining it once lets many subscriptions share the same price and terms, and changing the plan leaves existing subscriptions on the terms they signed. Defined by product or pricing managers; chosen when a subscription is made. A plan is followed by subscriptions. A plan is drafted, active while offered, and completed when no longer offered. It may be cancelled before use. Completed and cancelled are final. The "Premium annual" plan charges 480 a year and includes five users.', 'repeat', 'A', FALSE, FALSE, FALSE, TRUE, '2e53cd1a-834b-5a77-9a8d-7c1925acb59d', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
