VALUES ('d88a2e05-8f92-590f-872f-a84edfdad32a', '2e53cd1a-834b-5a77-9a8d-7c1925acb59d', 'd576d220-154b-5abf-b4d4-090d287ba1e3', 'Subscription Plan', 'Shows one Subscription Plan at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
