-- Usage Record (bus_usage_record)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('58729a5e-2d5c-5e06-8f18-9e9265cc4a87', 'Usage Record', 'Maintain Usage Record records', 'Create, find and maintain Usage Record records. The list shows every Usage Record you have access to — select a row to open it, or use New to add one. Each row is a single Usage Record, described by 3 fields.

Id is unique: no two Usage Record records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Usage Record points at Customer. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Usage Record then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Usage Record with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('37c07a66-2596-5ed8-96a3-9c75a7358e84', 'bus_usage_record', 'Usage Record', 'A fixed record of measured usage, either a single event or an aggregate, used for usage-based entitlement and billing. A usage record is the evidence of how much a customer consumed, such as minutes or gigabytes. It feeds billing and entitlement checks and, because it is never rewritten, can be shown to the customer if a charge is queried. Created by metering systems; read by billing and customer support. A usage record may relate to a customer. A record is drafted and becomes active when confirmed, then completed once billed. It may be cancelled if recorded in error. Completed and cancelled are final. 1,240 call minutes used by a customer in March are recorded as one usage record.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '58729a5e-2d5c-5e06-8f18-9e9265cc4a87', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d7f7bb85-30bb-5041-bd92-d23fa4681e37', '58729a5e-2d5c-5e06-8f18-9e9265cc4a87', '37c07a66-2596-5ed8-96a3-9c75a7358e84', 'Usage Record', 'Shows one Usage Record at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Customer is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
