-- --------------------------------------------------------------------------
-- Asset Class (bus_asset_class)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a17c2e00-772c-5837-9f96-8550724aa020', 'Asset Class', 'Maintain Asset Class records', 'Create, find and maintain Asset Class records. The list shows every Asset Class you have access to — select a row to open it, or use New to add one. Each row is a single Asset Class, described by 2 fields.

Id is unique: no two Asset Class records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Asset Class then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Asset Class with no rules or workflows attached is marked Final immediately.', 'box', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2571354d-ce6b-5724-8d40-b494355ae7c8', 'bus_asset_class', 'Asset Class', 'A classification of assets that carries default accounting, depreciation, lifecycle and control rules for every asset placed in it. Without classes every asset would need its own depreciation method and useful life. A class holds those policies once so assets of the same kind, such as vehicles, buildings or IT equipment, are treated consistently. Set up by asset accountants and policy owners; chosen when an asset is registered so its defaults are inherited. Assets are assigned to a class; the class''s accounting defaults feed depreciation and the ledger. A class is defined, used by assets, and eventually closed to new assets; history keeps the policy that applied when each asset was registered. The Vehicles class sets straight-line depreciation over five years and requires an insurance record for each asset.', 'box', 'A', FALSE, FALSE, FALSE, TRUE, 'a17c2e00-772c-5837-9f96-8550724aa020', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ee0e4397-958a-5597-8499-6f32abfb5193', 'a17c2e00-772c-5837-9f96-8550724aa020', '2571354d-ce6b-5724-8d40-b494355ae7c8', 'Asset Class', 'Shows one Asset Class at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
