INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c81295a-7d3d-5b47-b79e-0061c9cbfbee', 'Asset Acquisition', 'Maintain Asset Acquisition records', 'Create, find and maintain Asset Acquisition records. The list shows every Asset Acquisition you have access to — select a row to open it, or use New to add one. Each row is a single Asset Acquisition, described by 3 fields.

Id is unique: no two Asset Acquisition records may share the same value, and a save that would duplicate one is rejected. Asset must be filled in before the record can be saved.

Every Asset Acquisition points at Asset. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Asset Acquisition then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Asset Acquisition with no rules or workflows attached is marked Final immediately.', 'box', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2b3d6087-8e3b-5176-a027-cfe822b51687', 'bus_asset_acquisition', 'Asset Acquisition', 'The event by which an organisation takes on an asset, with the context needed to capitalise it, while the accounting entry itself stays in the journal. Acquiring an asset is a business event with its own date, source and cost. Recording it separately keeps the asset register and the ledger consistent without mixing the story of how the asset arrived into the asset itself. Created when an asset is purchased, built, leased in or received as a transfer in; read by asset accounting for capitalisation and depreciation start dates. Each acquisition refers to the Asset it brought into the register; the related JournalEntry holds the accounting posting. The event is recorded once and is then evidence. Errors are corrected by a compensating or superseding record rather than by editing the original. A forklift purchased on 3 March for 28,000 is recorded as an acquisition of that asset effective on delivery, from which depreciation starts.', 'box', 'A', FALSE, FALSE, FALSE, TRUE, '7c81295a-7d3d-5b47-b79e-0061c9cbfbee', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('21ea2a29-524e-5674-af52-606539b71313', '7c81295a-7d3d-5b47-b79e-0061c9cbfbee', '2b3d6087-8e3b-5176-a027-cfe822b51687', 'Asset Acquisition', 'Shows one Asset Acquisition at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Asset is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
