INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a4689981-0839-5b39-b982-512efdf7018e', 'Asset Transfer', 'Maintain Asset Transfer records', 'Create, find and maintain Asset Transfer records. The list shows every Asset Transfer you have access to — select a row to open it, or use New to add one. Each row is a single Asset Transfer, described by 3 fields.

Id is unique: no two Asset Transfer records may share the same value, and a save that would duplicate one is rejected. Asset must be filled in before the record can be saved.

Every Asset Transfer points at Asset. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Asset Transfer then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Asset Transfer with no rules or workflows attached is marked Final immediately.', 'box', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('02e49ab4-c007-5ee7-88a3-9f9f3e2bd931', 'bus_asset_transfer', 'Asset Transfer', 'The event by which responsibility for an asset, its location, organisational assignment or custody moves, without rewriting how the asset was acquired. Assets move between departments, sites and custodians during their life. A transfer records that move as an event, so the asset''s current owner and place are right while its earlier history stays intact. Created when an asset is relocated, reassigned or handed over; read to answer who held an asset when and for audits of custody. Each transfer points to the Asset that moved; the register reflects the latest effective transfer. A transfer is recorded once and is then evidence. A wrong transfer is corrected by a further transfer rather than an edit. A laptop moves from the Sales department in Berlin to Support in Madrid on 1 September.', 'box', 'A', FALSE, FALSE, FALSE, TRUE, 'a4689981-0839-5b39-b982-512efdf7018e', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
