INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0eaac3e9-5f4d-5220-84d8-033c8080e171', 'Foreign Exchange Transaction', 'Maintain Foreign Exchange Transaction records', 'Create, find and maintain Foreign Exchange Transaction records. The list shows every Foreign Exchange Transaction you have access to — select a row to open it, or use New to add one. Each row is a single Foreign Exchange Transaction, described by 2 fields.

Id is unique: no two Foreign Exchange Transaction records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Foreign Exchange Transaction then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Foreign Exchange Transaction with no rules or workflows attached is marked Final immediately.', 'file-text', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('42380ac1-995d-5fcf-b18d-72368954bfd9', 'bus_foreign_exchange_transaction', 'Foreign Exchange Transaction', 'An agreement or execution that exchanges one currency for another at defined amounts, rate, dates and counterparties. Whenever money changes currency, a rate is fixed and an obligation arises. This record preserves the terms so the gain or loss, the cash movement and the accounting can be explained. Created when a trade is agreed; settled on the value date; read by treasury and accounting. A transaction exchanges two currencies between counterparties and may be linked to payments and journal entries. Finalised financial evidence is corrected by compensating or superseding records, not edited. Buying 1,000,000 EUR for USD at 1.0840 for value in two days.', 'file-text', 'A', FALSE, FALSE, FALSE, TRUE, '0eaac3e9-5f4d-5220-84d8-033c8080e171', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
