VALUES ('f8803d41-de5e-5b12-8f4f-c9af94fc9fc5', 'bus_exchange_rate_rate_type', 'Exchange Rate Rate Type', 'The values of exchange rate rate type, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '7754098c-6c0e-59a7-bfbe-837840501383', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
