INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('795c914c-1e5a-5995-aa3f-97ac9398a7c2', 'Account Account Type', 'Maintain Account Account Type records', 'Create, find and maintain Account Account Type records. The list shows every Account Account Type you have access to — select a row to open it, or use New to add one. Each row is a single Account Account Type, described by 6 fields.

Id and Code are unique: no two Account Account Type records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Account Account Type then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Account Account Type with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b9e7303a-3f11-52b1-80e9-d6f53ba2d029', 'bus_account_account_type', 'Account Account Type', 'The values of account account type, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '795c914c-1e5a-5995-aa3f-97ac9398a7c2', 'U', TRUE, 'system', 'system', NOW(), NOW())
