INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('380f94b7-d33a-5cda-bffc-04bcdc044e91', 'Tax Registration Status', 'Maintain Tax Registration Status records', 'Create, find and maintain Tax Registration Status records. The list shows every Tax Registration Status you have access to — select a row to open it, or use New to add one. Each row is a single Tax Registration Status, described by 6 fields.

Id and Code are unique: no two Tax Registration Status records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Tax Registration Status then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tax Registration Status with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('52303136-a3ba-56ba-b169-c356ae54c46e', 'bus_tax_registration_status', 'Tax Registration Status', 'The values of tax registration status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '380f94b7-d33a-5cda-bffc-04bcdc044e91', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
