VALUES ('30e7044a-47f8-57b6-906c-0130566fd787', 'bus_asset_status', 'Asset Status', 'The values of asset status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'e5190a36-e585-5dfb-85fd-e3b13f9a324b', 'U', TRUE, 'system', 'system', NOW(), NOW())
