VALUES ('417b3a65-f2da-54d9-b4cb-3d7854410d50', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'tax_amount', 'Tax Amount', 'Tax originally recognized on the line. Historical tax component of the claim. Used for tax reporting, accounting and credit calculation. A credit line may reverse an eligible portion without editing this amount. Provides source tax evidence.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
