VALUES ('56511db6-8b6a-533c-aa45-db82140f1228', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'net_amount', 'Net Amount', 'Original net financial value of the line after discount and applicable tax treatment. Historical line contribution to the Invoice total. Used for billing, accounting and credit reference. Credit adjustment lines record a separate reduction rather than changing netAmount. Provides immutable source value.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
