INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('788538d1-bdd5-53bb-b73b-8f15268fb3b5', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'pricing_evidence', 'Pricing Evidence', 'Snapshot of material pricing inputs used to determine the invoice line amount. Preserves source, effective date, and approved commercial context needed to reproduce pricing even when master data changes. Supports audit, dispute resolution, recalculation, credit calculation and integration. Links the invoice result to the effective transaction price without making the posted invoice depend on mutable pricing master data.', 28, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('87eaa8f4-4f64-59d1-9fd0-84cfe131a2ac', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'discount_evidence', 'Discount Evidence', 'Snapshot of the discount policy inputs and result used on the invoice line. Preserves the applied discount rule/version, method, base, rate or fixed amount, and resulting discount. Supports audit and prevents later DiscountRule changes from altering historical calculations or credits. Provides reproducible discount calculation evidence.', 28, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ebec2e44-0676-5339-8223-6dd4ff929b8b', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'tax_evidence', 'Tax Evidence', 'Snapshot of the tax determination inputs and result used on the invoice line. Preserves tax rule/version, jurisdiction, rate, taxable base, rounding and calculated tax. Supports tax audit, compliance, dispute resolution and credit-note tax calculation. Prevents later TaxRule changes from rewriting posted invoice tax.', 28, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0373c7d1-2f34-55a0-977e-9f0a91b3dc72', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'description', 'Description', 'Human-readable description of the original billed line. Describes the billed good or service. Used on documents and audit. Complements Product and source transaction references. Supports document presentation.', 10, 1000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9aa8cc3e-2916-515f-8fef-b86889c44d47', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'matching_status', 'Matching Status', 'Whether the line has been checked against the order and receipt it bills for. Set by the three-way matching process; lines in EXCEPTION block payment until they are resolved or waived. The line does not need matching, for example a sales invoice line. Not yet compared with the purchase order and goods receipt. Quantity and price agree with the order and receipt within tolerance. Some of the line''s quantity or amount agrees; the rest does not. A difference outside tolerance needs a decision. The difference was accepted by an authorised approver. Indicates whether the line agrees with applicable purchase and receipt evidence. Independent from CreditNote and SupplierCreditNote status; a credit may correct a posted line after matching. Controls matching approval before posting.', 1022, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3fb7514d-6b06-5bf8-a91b-29b64cd89227', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'unit_of_measure_id', 'Unit Of Measure', 'Unit in which the original quantity was billed. Defines measurement semantics for the historical quantity. Supports billing, fulfillment and return conversion. Provides source measurement context for eligible credits.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('744590b5-3a1f-5535-8f2a-01abdc9d7663', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'invoice_id', 'Invoice', 'Parent invoice containing the original claim line. Provides financial document context. Supports billing, settlement, adjustment and audit. Parent claim owns the line''s historical calculation.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 160, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a364cdbe-c1d4-5e96-a528-13e1a6fb9d14', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'product_id', 'Product', 'Product or service identified by the original invoice line. Identifies what was billed without making current product master data a live dependency of posted history. Supports billing, fulfillment and return traceability. Supplies source item context.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 170, 'U', TRUE, 'system', 'system', NOW(), NOW())
