VALUES ('bf378c75-e063-54e7-9c94-e76270a90fe3', 'b8dc4f76-ead7-50e4-a3e7-e5088161d4a3', 'purchase_order_line_id', 'Purchase Order Line', 'Procurement line associated with a purchase invoice line. Connects payable billing to the original procurement commitment. Supports three-way matching and supplier-return traceability. Supplies source procurement evidence.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 180, 'U', TRUE, 'system', 'system', NOW(), NOW())
