VALUES ('513df647-3946-5a00-a27c-de97bc3c131a', 'fa633387-3b8e-51d5-af12-01472d59b222', '03893fee-5b4b-5186-a56a-8d9a5aca8ee9', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'Immutable identity of the original invoice line. Identifies the historical billed detail independently of later credits or corrections. Used for billing, audit, matching, credit and reconciliation. CreditNoteLine and SupplierCreditNoteLine may reference this identity as source evidence. Stable root reference for the line lifecycle. Must be unique: a save is rejected if another Invoice Line already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('16eeb82a-d657-5e79-bd08-792c56071abc', 'fa633387-3b8e-51d5-af12-01472d59b222', 'b4b69893-e6d4-5ea7-a4e6-78f2765b70f8', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Line Number', 'Sequence number within the invoice. Identifies the line for documents and reconciliation. Used in invoice presentation and audit. Unique within Invoice and distinct from CreditNoteLine and SupplierCreditNoteLine numbering. Supports deterministic document reconstruction. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
