ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3a8a5010-cba8-5874-a4fb-60b091b6c245', 'fa633387-3b8e-51d5-af12-01472d59b222', 'fc4698cc-5c6a-5556-adbe-c9e8d4958f8d', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Unit Price', 'Transaction-time billed price per unit. Captures the price actually used to value the invoice line, not today''s master price. Supports invoice calculation, audit, price variance, settlement and credit calculation. Customer or supplier credit lines may preserve this as source valuation evidence; later pricing changes do not rewrite it. Provides authoritative historical pricing evidence for the invoice line.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
