INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9f4b5995-46cd-596a-9bb5-21efffbe6df1', 'fa633387-3b8e-51d5-af12-01472d59b222', '0373c7d1-2f34-55a0-977e-9f0a91b3dc72', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Description', 'Human-readable description of the original billed line. Describes the billed good or service. Used on documents and audit. Complements Product and source transaction references. Supports document presentation. Up to 1000 characters.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3c49db20-3ca1-5396-9759-835b8cbe7f48', 'fa633387-3b8e-51d5-af12-01472d59b222', '9aa8cc3e-2916-515f-8fef-b86889c44d47', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Matching Status', 'Whether the line has been checked against the order and receipt it bills for. Set by the three-way matching process; lines in EXCEPTION block payment until they are resolved or waived. The line does not need matching, for example a sales invoice line. Not yet compared with the purchase order and goods receipt. Quantity and price agree with the order and receipt within tolerance. Some of the line''s quantity or amount agrees; the rest does not. A difference outside tolerance needs a decision. The difference was accepted by an authorised approver. Indicates whether the line agrees with applicable purchase and receipt evidence. Independent from CreditNote and SupplierCreditNote status; a credit may correct a posted line after matching. Controls matching approval before posting. Required — the record cannot be saved while this is empty.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('caa8933f-93db-5006-b910-3cee1b215989', 'fa633387-3b8e-51d5-af12-01472d59b222', '3fb7514d-6b06-5bf8-a91b-29b64cd89227', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Unit Of Measure', 'Unit in which the original quantity was billed. Defines measurement semantics for the historical quantity. Supports billing, fulfillment and return conversion. Provides source measurement context for eligible credits.', 150, 150, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ecc4e908-3607-5028-85dd-18b2d76d8798', 'fa633387-3b8e-51d5-af12-01472d59b222', '744590b5-3a1f-5535-8f2a-01abdc9d7663', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Invoice', 'Parent invoice containing the original claim line. Provides financial document context. Supports billing, settlement, adjustment and audit. Parent claim owns the line''s historical calculation. Required — the record cannot be saved while this is empty.', 160, 160, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6c9367e-27a2-5d90-98a0-6b114112c175', 'fa633387-3b8e-51d5-af12-01472d59b222', 'a364cdbe-c1d4-5e96-a528-13e1a6fb9d14', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Product', 'Product or service identified by the original invoice line. Identifies what was billed without making current product master data a live dependency of posted history. Supports billing, fulfillment and return traceability. Supplies source item context.', 170, 170, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2c25efca-8b45-5855-b5f3-e01c1cf59f27', 'fa633387-3b8e-51d5-af12-01472d59b222', 'bf378c75-e063-54e7-9c94-e76270a90fe3', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Purchase Order Line', 'Procurement line associated with a purchase invoice line. Connects payable billing to the original procurement commitment. Supports three-way matching and supplier-return traceability. Supplies source procurement evidence.', 180, 180, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5c7897ce-8576-5974-b585-220395283562', 'fa633387-3b8e-51d5-af12-01472d59b222', 'f095d7da-8940-58a7-94db-9cefa8c6b988', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Sales Order Line', 'The SalesOrderLine this InvoiceLine belongs to.', 190, 190, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
