-- --------------------------------------------------------------------------
-- Credit Note Line (bus_credit_note_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('06f120cc-44b9-556b-a325-fb08a1bb956e', 'bus_credit_note_line', 'Credit Note Line', 'Represents one auditable financial adjustment detail and its source evidence. CreditNoteLine translates an eligible original invoice or return into a specific credited value while preserving historical source facts. Return credits, billing corrections, tax adjustments, customer concessions and audit. InvoiceLine is the original financial evidence; CustomerReturnLine is the reverse-fulfillment evidence; CreditNoteLine is the new financial result. Validate source → determine eligible quantity/value → apply return and pricing/tax policy → snapshot evidence → calculate line credit → approve → post through CreditNote. Corrections use reversal/replacement. Draft → calculated → approved → posted, with controlled reversal after posting. Three returned units are eligible for credit at the original transaction value. CreditNoteLine records quantity 3, preserves the source InvoiceLine and CustomerReturnLine, recalculates applicable tax, and contributes its total to CreditNote without changing the original invoice line.', 'credit-card', 'A', FALSE, FALSE, FALSE, TRUE, '88634eaa-67df-5b93-be1e-cab32f218399', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9c3346d4-879a-551b-b71e-60f0500eb2b2', '88634eaa-67df-5b93-be1e-cab32f218399', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'Credit Note Line', 'Shows one Credit Note Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 7 fields marked with a red asterisk (*) must have a value before Save will accept the record. Invoice Line and Credit Note are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ab690b5-9289-541d-be15-da2a3d88c69a', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'id', 'Id', 'Immutable identity of the credit-note line. Identifies one financial adjustment detail independently of its source invoice or return. Used for accounting, audit, reconciliation, tax and correction workflows. Links the line to CreditNote while preserving distinct source InvoiceLine and CustomerReturnLine identities. Stable reference for calculation, posting and reversal.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b226100b-2707-5549-9b25-c5e63d396989', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'line_number', 'Line Number', 'Business sequence number within the CreditNote. Orders the adjustment details for document presentation and audit. Used for documents, reconciliation and integrations. Unique within the parent CreditNote and independent of original InvoiceLine.lineNumber. Supports deterministic document reconstruction.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('672dfa52-809f-5fdd-b4c2-83e324ce9acb', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'quantity', 'Quantity', 'Quantity being financially credited when the adjustment is quantity-based. Represents the credited quantity, which may be less than or equal to the returned quantity or originally billed quantity. Used for return credits, quantity corrections and reconciliation. Must reconcile with eligible source InvoiceLine and CustomerReturnLine quantities. Feeds line valuation where credit is quantity-derived.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('43e43e93-1226-5206-99c9-c21f992f075d', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'unit_price', 'Unit Price', 'Transaction-time unit value used to calculate the credit where applicable. Preserves the original or policy-approved value rather than using mutable current pricing. Supports reproducibility, dispute resolution and audit. Should reconcile with source InvoiceLine pricing evidence or authorized return-credit policy. Supplies valuation evidence for quantity-based credits.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('77f4a35c-da82-53ad-aef5-24d485d978e3', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'subtotal', 'Subtotal', 'Pre-tax monetary credit represented by this line. The line''s financial base before credited tax. Used for CreditNote calculation, accounting and reconciliation. Must reconcile with quantity, unitPrice, discounts and source evidence where applicable. Feeds taxable amount and total line credit.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('229e4300-a6a1-53ae-a7fb-89c3daace6eb', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'discount_amount', 'Discount Amount', 'Discount component included in determining the credited line value. Preserves the applicable discount treatment from the original transaction or return policy. Used for reconciliation and tax calculation. Must not be confused with a new settlement discount. Determines the credited taxable base according to policy.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('faa5cdf7-9037-5dbb-8819-eab10f73fd57', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'taxable_amount', 'Taxable Amount', 'Taxable base of the credited line. Amount to which applicable tax treatment is applied for the credit. Used for tax reporting and accounting. Must reconcile with original InvoiceLine tax treatment or authorized correction policy. Feeds credited tax calculation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('341ea865-e9c4-5711-9b70-1822be084ace', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'tax_amount', 'Tax Amount', 'Tax amount reversed or credited on this line. Represents the tax consequence of the credited value. Used for tax reporting, accounting and reconciliation. Must reconcile with applicable TaxRule and source invoice tax evidence. Contributes to the line''s total credit.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4a0583a-96fc-5709-adb3-f6599d776096', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'total_amount', 'Total Amount', 'Total credit represented by this line including applicable tax. Financial reduction attributable to this specific adjustment detail. Aggregated into CreditNote.totalAmount and used for accounting/application. Does not mutate the original InvoiceLine amount. Provides authoritative line contribution to the CreditNote total.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('174ad2ab-95f7-5fd9-9da4-bb1f076c7a99', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'pricing_evidence', 'Pricing Evidence', 'Snapshot of material valuation inputs used for the credited amount. Preserves original price, source, effective date or authorized override required to reproduce the credit. Supports audit and dispute resolution. Connects valuation to original InvoiceLine evidence without making the credit depend on current price master data. Provides historical calculation evidence.', 28, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eead4f87-2763-5b76-9662-40cfd4d8a18b', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'tax_evidence', 'Tax Evidence', 'Snapshot of material tax inputs used to determine credited tax. Preserves tax rule/version, jurisdiction, rate, base and rounding used for the adjustment. Supports tax audit and historical reproducibility. Should reconcile with source InvoiceLine tax evidence and applicable correction policy. Supports deterministic tax calculation and posting.', 28, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('75c39506-92fd-53b1-bf8e-94db6687b5be', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'invoice_line_id', 'Invoice Line', 'Original billed line from which the credit is derived or corrected. Preserves the financial claim basis without modifying its historical values. Supports return credit, billing correction, tax correction and audit. Supplies eligible quantity, price, discount and tax evidence.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1f64b92d-2a75-54cc-846c-30594f072eae', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'credit_note_id', 'Credit Note', 'Parent financial adjustment document containing this line. Establishes the document context for the adjustment detail. Supports aggregation, approval, posting and audit. Line totals feed the parent CreditNote totals and lifecycle.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
UPDATE sys_tab SET link_column_id = '1f64b92d-2a75-54cc-846c-30594f072eae' WHERE sys_tab_id = '9c3346d4-879a-551b-b71e-60f0500eb2b2';
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('732f9001-f6ae-5f72-918e-069200e03216', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '6ab690b5-9289-541d-be15-da2a3d88c69a', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'Immutable identity of the credit-note line. Identifies one financial adjustment detail independently of its source invoice or return. Used for accounting, audit, reconciliation, tax and correction workflows. Links the line to CreditNote while preserving distinct source InvoiceLine and CustomerReturnLine identities. Stable reference for calculation, posting and reversal. Must be unique: a save is rejected if another Credit Note Line already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0e2492c8-f514-5ecf-8b33-d38465bd0713', '9c3346d4-879a-551b-b71e-60f0500eb2b2', 'b226100b-2707-5549-9b25-c5e63d396989', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Line Number', 'Business sequence number within the CreditNote. Orders the adjustment details for document presentation and audit. Used for documents, reconciliation and integrations. Unique within the parent CreditNote and independent of original InvoiceLine.lineNumber. Supports deterministic document reconstruction. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('117f9aec-d3bd-5d89-86ff-73eb68cc8b2c', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '672dfa52-809f-5fdd-b4c2-83e324ce9acb', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Quantity', 'Quantity being financially credited when the adjustment is quantity-based. Represents the credited quantity, which may be less than or equal to the returned quantity or originally billed quantity. Used for return credits, quantity corrections and reconciliation. Must reconcile with eligible source InvoiceLine and CustomerReturnLine quantities. Feeds line valuation where credit is quantity-derived.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ac31f29f-c4b4-54a0-a0e1-7323ed6a5d47', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '43e43e93-1226-5206-99c9-c21f992f075d', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Unit Price', 'Transaction-time unit value used to calculate the credit where applicable. Preserves the original or policy-approved value rather than using mutable current pricing. Supports reproducibility, dispute resolution and audit. Should reconcile with source InvoiceLine pricing evidence or authorized return-credit policy. Supplies valuation evidence for quantity-based credits.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0972efb9-15f9-5a4b-a657-a1f1b9769283', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '77f4a35c-da82-53ad-aef5-24d485d978e3', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Subtotal', 'Pre-tax monetary credit represented by this line. The line''s financial base before credited tax. Used for CreditNote calculation, accounting and reconciliation. Must reconcile with quantity, unitPrice, discounts and source evidence where applicable. Feeds taxable amount and total line credit. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('79d0ee8f-81b6-5a80-aee0-efb095eafb9b', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '229e4300-a6a1-53ae-a7fb-89c3daace6eb', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Discount Amount', 'Discount component included in determining the credited line value. Preserves the applicable discount treatment from the original transaction or return policy. Used for reconciliation and tax calculation. Must not be confused with a new settlement discount. Determines the credited taxable base according to policy. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1f86d75f-6c4a-5780-a6cc-456eec07dc84', '9c3346d4-879a-551b-b71e-60f0500eb2b2', 'faa5cdf7-9037-5dbb-8819-eab10f73fd57', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Taxable Amount', 'Taxable base of the credited line. Amount to which applicable tax treatment is applied for the credit. Used for tax reporting and accounting. Must reconcile with original InvoiceLine tax treatment or authorized correction policy. Feeds credited tax calculation. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4327e443-96c1-5268-889e-061daaefe45e', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '341ea865-e9c4-5711-9b70-1822be084ace', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Tax Amount', 'Tax amount reversed or credited on this line. Represents the tax consequence of the credited value. Used for tax reporting, accounting and reconciliation. Must reconcile with applicable TaxRule and source invoice tax evidence. Contributes to the line''s total credit. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d0e2c58-2f02-57ba-b6da-cf2861b2e457', '9c3346d4-879a-551b-b71e-60f0500eb2b2', 'd4a0583a-96fc-5709-adb3-f6599d776096', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Total Amount', 'Total credit represented by this line including applicable tax. Financial reduction attributable to this specific adjustment detail. Aggregated into CreditNote.totalAmount and used for accounting/application. Does not mutate the original InvoiceLine amount. Provides authoritative line contribution to the CreditNote total. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd0d55d3-fd7b-5e91-a116-470c8f2abe21', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '174ad2ab-95f7-5fd9-9da4-bb1f076c7a99', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Pricing Evidence', 'Snapshot of material valuation inputs used for the credited amount. Preserves original price, source, effective date or authorized override required to reproduce the credit. Supports audit and dispute resolution. Connects valuation to original InvoiceLine evidence without making the credit depend on current price master data. Provides historical calculation evidence.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2fef3d9c-e541-5b29-bfb1-3929a655972b', '9c3346d4-879a-551b-b71e-60f0500eb2b2', 'eead4f87-2763-5b76-9662-40cfd4d8a18b', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Tax Evidence', 'Snapshot of material tax inputs used to determine credited tax. Preserves tax rule/version, jurisdiction, rate, base and rounding used for the adjustment. Supports tax audit and historical reproducibility. Should reconcile with source InvoiceLine tax evidence and applicable correction policy. Supports deterministic tax calculation and posting.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5d3dc080-82cc-5354-90ee-f887e9e50fb0', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '75c39506-92fd-53b1-bf8e-94db6687b5be', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Invoice Line', 'Original billed line from which the credit is derived or corrected. Preserves the financial claim basis without modifying its historical values. Supports return credit, billing correction, tax correction and audit. Supplies eligible quantity, price, discount and tax evidence.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d9635459-e1ec-5263-a1fc-140a1376a147', '9c3346d4-879a-551b-b71e-60f0500eb2b2', '1f64b92d-2a75-54cc-846c-30594f072eae', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Credit Note', 'Parent financial adjustment document containing this line. Establishes the document context for the adjustment detail. Supports aggregation, approval, posting and audit. Line totals feed the parent CreditNote totals and lifecycle. Required — the record cannot be saved while this is empty.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
