-- --------------------------------------------------------------------------
-- Purchase Order Line (bus_purchase_order_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ed7cfac9-ad9d-532c-a423-c2ceda82c1df', 'bus_purchase_order_line', 'Purchase Order Line', 'One item ordered on a purchase order, with the quantity, price and the progress of receipt, invoicing and return. The line is where the commitment is made precise: which product, how many, at what price and from what source. It keeps the price as agreed at the time and tracks what has since arrived, been accepted, returned and is still owed, so the order''s completion can be judged line by line. Created with the order, from a requisition or quotation line; updated as goods arrive; read by receiving, accounts payable and buyers. A line belongs to one order and product, may come from a quotation or requisition line, and is matched by receipt, invoice and return lines. A line follows its order: open until fully received, then settled. Its quantities change only through receipts and returns. Line 2 of PO-5120 orders 400 bolts at 0.35 each; 250 have been received and 150 are outstanding. Pricing → commitment → receipt → acceptance → InventoryMovement; if goods are returned, eligible accepted quantity → SupplierReturnLine → InventoryMovement reversal → SupplierCreditNoteLine. Historical commitment remains unchanged.', 'shopping-cart', 'A', FALSE, FALSE, FALSE, TRUE, '3863b9c0-9e3d-5723-a62a-655d9c55334b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81b88618-9fee-5cd7-8cf0-df5f6e8a2202', '3863b9c0-9e3d-5723-a62a-655d9c55334b', 'ed7cfac9-ad9d-532c-a423-c2ceda82c1df', 'Purchase Order Line', 'Shows one Purchase Order Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 10 fields marked with a red asterisk (*) must have a value before Save will accept the record. Unit Of Measure, Purchase Order and Product are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d62231c7-575a-5906-abb0-455c7e0623a6', 'ed7cfac9-ad9d-532c-a423-c2ceda82c1df', 'id', 'Id', 'The identity of the line, constant for its life. Generated on creation; receipt and invoice lines refer to it. Referenced when matching receipts and invoices.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('161805b4-1f15-5a13-bc16-ab4eb0dc724a', 'ed7cfac9-ad9d-532c-a423-c2ceda82c1df', 'line_number', 'Line Number', 'The position of the line on the order. Assigned in sequence; used to refer to the line in documents. Read with the order number to name a line.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2bc2edde-f88e-563f-a0d9-b655f1861891', 'ed7cfac9-ad9d-532c-a423-c2ceda82c1df', 'quantity', 'Quantity', 'The quantity ordered, in the line''s unit of measure. Entered when ordering; receipts are measured against it. Compared with received quantity to find what is outstanding.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d7a32279-29cb-50ef-a0f8-6abf6926f8e9', 'ed7cfac9-ad9d-532c-a423-c2ceda82c1df', 'unit_price', 'Unit Price', 'The price for one unit, as agreed when the order was placed. Set from the price source; kept even if prices later change. Multiplied by quantity to give the line amount.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
